input.newString:
Cmd::Read {
    channel,
    before,
    after,
    limit,
    all,
} => {
    anyhow::ensure!(
        (1..=200).contains(&limit),
        "Limit must be 1-200"
    );
    anyhow::ensure!(
        !(before.is_some() && after.is_some()),
        "Use --before or --after, not both"
    );
    // Resolve names/@users exactly once, before any paging.
    let cid = c.resolve_channel(&channel)?;
    if !all {
        let mut path = format!("/channels/{cid}/messages?limit={limit}");
        if let Some(v) = before {
            path.push_str(&format!("&before={}", id(&v)?));
        }
        if let Some(v) = after {
            path.push_str(&format!("&after={}", id(&v)?));
        }
        print(&c.get::<Vec<Message>>(&path)?)?;
    } else {
        // before/no cursor: newest page first, walk backwards.
        // after: oldest page first, walk forwards.
        let cursor = match &before {
            Some(v) => Some(("before", id(v)?.to_string())),
            None => after.as_ref().map(|v| ("after", id(v)?.to_string())),
        };
        let mut pages: Vec<Vec<Message>> = Vec::new();
        let mut seen_first: Option<String> = None;
        loop {
            let mut path = format!("/channels/{cid}/messages?limit={limit}");
            if let Some((key, value)) = &cursor {
                path.push_str(&format!("&{key}={value}"));
            }
            let page: Vec<Message> = c.get(&path)?;
            if let Some(first) = page.first() {
                if seen_first.as_deref() == Some(first.id.as_str()) {
                    anyhow::bail!("Message listing did not advance; aborting --all");
                }
                seen_first = Some(first.id.clone());
            }
            let done = page.len() < limit as usize;
            pages.push(page);
            if done {
                break;
            }
            // The next cursor is the last id of this page, exclusive.
            let last = pages
                .last()
                .and_then(|p| p.last())
                .map(|m| m.id.clone())
                .context("Empty page before the end of the listing")?;
            match cursor {
                Some(("after", _)) => {
                    let after = last.clone();
                    let path =
                        format!("/channels/{cid}/messages?limit={limit}&after={after}");
                    let next: Vec<Message> = c.get(&path)?;
                    if let Some(first) = next.first() {
                        if seen_first.as_deref() == Some(first.id.as_str()) {
                            anyhow::bail!(
                                "Message listing did not advance; aborting --all"
                            );
                        }
                        seen_first = Some(first.id.clone());
                    }
                    let done = next.len() < limit as usize;
                    pages.push(next);
                    if done {
                        break;
                    }
                    cursor_forward(&cid, limit, &after, &mut pages, &mut seen_first)?;
                    break;
                }
                _ => {
                    // Walk backwards: query with before=last id.
                    let path =
                        format!("/channels/{cid}/messages?limit={limit}&before={last}");
                    let next: Vec<Message> = c.get(&path)?;
                    if let Some(first) = next.first() {
                        if seen_first.as_deref() == Some(first.id.as_str()) {
                            anyhow::bail!(
                                "Message listing did not advance; aborting --all"
                            );
                        }
                        seen_first = Some(first.id.clone());
                    }
                    if next.is_empty() {
                        break;
                    }
                    let done = next.len() < limit as usize;
                    pages.push(next);
                    if done {
                        break;
                    }
                }
            }
        }
        let mut merged: BTreeMap<String, Message> = BTreeMap::new();
        for page in pages {
            for m in page {
                merged.insert(m.id.clone(), m);
            }
        }
        let merged: Vec<Message> = merged.into_values().collect();
        print(&merged)?;
    }
}

