    let direction = match &before {
        Some(v) => ("before", id(v)?.to_string()),
        None => match &after {
            Some(v) => ("after", id(v)?.to_string()),
            None => ("before", String::new()),
        },
    };
    let use_before = direction.0 == "before";
    let mut cursor = direction.1;
    let mut merged: BTreeMap<String, Message> = BTreeMap::new();
    loop {
        let mut path = format!("/channels/{cid}/messages?limit={limit}");
        // An empty cursor means no bound: start from the newest page.
        if !cursor.is_empty() {
            let key = if use_before { "before" } else { "after" };
            path.push_str(&format!("&{key}={cursor}"));
        }
        let page: Vec<Message> = c.get(&path)?;
        let first = page.first().map(|m| m.id.clone());
        if let Some(first) = &first {
            // A full page repeating its newest id means the server
            // is not advancing past the cursor; fail instead of hanging.
            if merged.contains_key(first) && page.len() == limit as usize {
                anyhow::bail!("Message listing did not advance; aborting --all");
            }
        }
        for m in page {
            merged.insert(m.id.clone(), m);
        }
        // A short page means we have reached the end of the range.
        let done = first.is_none()
            || merged.len() % limit as usize != 0 && {
                // recompute below via next cursor instead
                false
            };
