            .values()
            .filter(|m| {
                if use_before {
                    cursor.is_empty() || &m.id < &cursor
                } else {
                    &m.id > &cursor
                }
            })
            .next_back()
            .map(|m| m.id.clone());
        match last {
            Some(last) => cursor = last,
            None => break,
        }
        let _ = done;
        if first.is_none() {
            break;
        }
    }
    let merged: Vec<Message> = merged.into_values().collect();
